syntax = "proto3";

package operation.v1;

import "google/protobuf/struct.proto";

// Client-side mirror of the single gated mutation entry point.
//
// Source of truth:
//   operation-dbus-proto/crates/op-grpc-bridge/proto/operation.proto
//
// Only PluginService.CallMethod is mirrored here. The gRPC contract is keyed by
// package/service/method and field numbers, which must stay wire-compatible with
// the server. Object paths and plugin leaves are NOT hardcoded in this client;
// they are discovered at runtime by introspecting the projected D-Bus tree
// (org.opdbus.v1.plugins), keeping that tree the single source of truth.
service PluginService {
  // Invoke a plugin method through the authoritative MutationEngine.
  rpc CallMethod(CallMethodRequest) returns (CallMethodResponse);
}

message CallMethodRequest {
  string plugin_id = 1;
  string object_path = 2;
  string interface_name = 3;
  string method_name = 4;
  repeated google.protobuf.Value arguments = 5;
  string actor_id = 6;
  string capability_id = 7;
}

message CallMethodResponse {
  bool success = 1;
  google.protobuf.Value result = 2;
  uint64 event_id = 3;
  string event_hash = 4;
  MutationError error = 5;
}

// Field numbers match the server's MutationError; deny_reason (field 3) is a
// nested message there and is intentionally omitted, prost skips it on decode.
message MutationError {
  ErrorCode code = 1;
  string message = 2;
}

enum ErrorCode {
  ERROR_CODE_UNSPECIFIED = 0;
  ERROR_CODE_NOT_FOUND = 1;
  ERROR_CODE_PERMISSION_DENIED = 2;
  ERROR_CODE_VALIDATION_FAILED = 3;
  ERROR_CODE_READ_ONLY = 4;
  ERROR_CODE_TAG_LOCKED = 5;
  ERROR_CODE_INTERNAL = 6;
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    tonic_build::configure()
        .build_server(false)
        .compile_protos(&["proto/operation_plugin.proto"], &["proto"])?;
    println!("cargo:rerun-if-changed=proto/operation_plugin.proto");
    Ok(())
}

use clap::{Args, Parser, Subcommand};
use serde_json::json;
use zbus::Connection;
use zbusctl::build_body;
use zvariant::Structure;

use hyper_util::rt::TokioIo;
use tokio::net::UnixStream;
use tonic::metadata::{Ascii, MetadataValue};
use tonic::transport::Endpoint;

use operation_v1::plugin_service_client::PluginServiceClient;
use operation_v1::CallMethodRequest;

pub mod operation_v1 {
    tonic::include_proto!("operation.v1");
}

/// The single stable root anchor. Everything below it is discovered from the
/// live projected tree, never hardcoded.
const PLUGINS_ROOT_NAME: &str = "org.opdbus.v1.plugins";
const PLUGINS_ROOT_PATH: &str = "/org/opdbus/v1/plugins";
/// 152-byte repr(C) Identity Sled written by the SchemaEngine into tmpfs.
const SLED_PATH: &str = "/dev/shm/plugin_schema.dat";
const DEFAULT_GRPC_SOCKET: &str = "/run/opdbus/zeroclaw-grpc.sock";
const TARGET_PLUGIN: &str = "unix_socket";
const CREATE_METHOD: &str = "createunixsocket";

#[derive(Parser)]
#[command(version = env!("CARGO_PKG_VERSION"))]
#[command(about = "A command-line utility for interacting with D-Bus")]
struct ZBusCtl {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Call a D-Bus method with typed arguments
    Call(CallArgs),
    /// Provision a Unix socket endpoint through the unix_socket plugin
    Createsocket(CreateSocketArgs),
}

#[derive(Args)]
struct CallArgs {
    #[arg(long, help = "Use system bus instead of session bus")]
    system: bool,

    #[arg(short, long, help = "D-Bus service name")]
    service: String,

    #[arg(short, long, help = "D-Bus object path")]
    object: String,

    #[arg(short, long, help = "D-Bus interface name")]
    interface: String,

    #[arg(short, long, help = "D-Bus method name")]
    method: String,

    #[arg(help = "D-Bus method arguments")]
    args: Option<Vec<String>>,
}

#[derive(Args)]
struct CreateSocketArgs {
    /// Discover on the session bus instead of the system bus (projection authority)
    #[arg(long)]
    session: bool,

    /// Socket label / name (becomes the demux tag and plugin record identity)
    #[arg(long)]
    name: String,

    /// Advisory socket path hint. The backend binds the shared container socket
    /// regardless; retained for CLI compatibility.
    #[arg(long)]
    path: Option<String>,

    /// Comma-separated TCP ports proxied into the socket
    #[arg(long, value_delimiter = ',')]
    port: Vec<u16>,

    /// Transport protocol carried over the socket
    #[arg(long, default_value = "grpc")]
    protocol: String,

    /// Native gRPC Unix socket of the gated mutation surface
    /// (default: $ZEROCLAW_UNIX_SOCKET or /run/opdbus/zeroclaw-grpc.sock)
    #[arg(long)]
    grpc_socket: Option<String>,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let args = ZBusCtl::parse();

    match args.command {
        Commands::Call(call) => run_call_command(call).await?,
        Commands::Createsocket(cs) => run_createsocket_command(cs).await?,
    }

    Ok(())
}

async fn run_call_command(args: CallArgs) -> zbus::Result<()> {
    let connection = if args.system {
        Connection::system().await?
    } else {
        Connection::session().await?
    };

    let body = if let Some(args) = args.args {
        Some(build_body(args.iter().map(|s| s.as_str()).collect())?)
    } else {
        None
    };

    let result = match body {
        Some(ref body) => {
            connection
                .call_method(
                    Some(args.service.as_str()),
                    args.object.as_str(),
                    Some(args.interface.as_str()),
                    args.method.as_str(),
                    body,
                )
                .await?
        }
        None => {
            connection
                .call_method(
                    Some(args.service.as_str()),
                    args.object.as_str(),
                    Some(args.interface.as_str()),
                    args.method.as_str(),
                    &(),
                )
                .await?
        }
    };

    let result_body = result.body().clone();
    let response = result_body.deserialize::<Structure>()?;

    let response_json = serde_json::to_value(&response.fields()[0])
        .map_err(|e| zbus::Error::Failure(format!("Failed to convert response to JSON: {}", e)))?;

    println!("{}", response_json);

    Ok(())
}

/// Provision a socket by discovering the unix_socket leaf from the projected
/// D-Bus tree and mutating through the single gated gRPC door
/// (operation.v1.PluginService.CallMethod -> MutationEngine).
async fn run_createsocket_command(args: CreateSocketArgs) -> anyhow::Result<()> {
    if args.port.is_empty() {
        anyhow::bail!("at least one --port is required");
    }

    // 1. DISCOVER. Hardcoding stops at the root anchor; the unix_socket leaf is
    //    resolved from the live tree so a rename fails loudly here instead of
    //    silently dialing a dead address.
    let bus_label = if args.session { "session" } else { "system" };
    let connection = if args.session {
        Connection::session().await?
    } else {
        Connection::system().await?
    };

    let introspectable = zbus::Proxy::new(
        &connection,
        PLUGINS_ROOT_NAME,
        PLUGINS_ROOT_PATH,
        "org.freedesktop.DBus.Introspectable",
    )
    .await
    .map_err(|e| anyhow::anyhow!("cannot reach {PLUGINS_ROOT_NAME} on the {bus_label} bus: {e}"))?;

    let xml: String = introspectable
        .call("Introspect", &())
        .await
        .map_err(|e| anyhow::anyhow!("introspecting {PLUGINS_ROOT_NAME} failed on the {bus_label} bus: {e}"))?;

    let plugins = child_node_names(&xml);
    if !plugins.iter().any(|p| p == TARGET_PLUGIN) {
        let found = if plugins.is_empty() {
            "<none>".to_string()
        } else {
            plugins.join(", ")
        };
        anyhow::bail!(
            "plugin '{TARGET_PLUGIN}' is not present under {PLUGINS_ROOT_NAME} (discovered: {found}); \
             refusing to dial a hardcoded leaf"
        );
    }
    let object_path = format!("{PLUGINS_ROOT_PATH}/{TARGET_PLUGIN}");

    // 2. AUTH. Read the Ghostbridge identity straight from the live Identity Sled
    //    (the primary source in tmpfs), not a projection of it.
    let (footprint, trace_id) = read_sled_identity()?;
    let footprint_meta: MetadataValue<Ascii> = footprint
        .parse()
        .map_err(|e| anyhow::anyhow!("invalid footprint header value: {e}"))?;
    let trace_meta: MetadataValue<Ascii> = trace_id
        .parse()
        .map_err(|e| anyhow::anyhow!("invalid trace-id header value: {e}"))?;

    // 3. Dial the gated gRPC mutation surface over its native Unix socket.
    let grpc_socket = args
        .grpc_socket
        .clone()
        .or_else(|| std::env::var("ZEROCLAW_UNIX_SOCKET").ok())
        .unwrap_or_else(|| DEFAULT_GRPC_SOCKET.to_string());
    let dial_socket = grpc_socket.clone();
    let channel = Endpoint::try_from("http://127.0.0.1:50051")?
        .connect_with_connector(tower::service_fn(move |_| {
            let dial_socket = dial_socket.clone();
            async move {
                let stream = UnixStream::connect(dial_socket).await?;
                Ok::<_, std::io::Error>(TokioIo::new(stream))
            }
        }))
        .await
        .map_err(|e| anyhow::anyhow!("gRPC connect to {grpc_socket} failed: {e}"))?;

    let mut client =
        PluginServiceClient::with_interceptor(channel, move |mut req: tonic::Request<()>| {
            req.metadata_mut()
                .insert("x-ghostbridge-footprint", footprint_meta.clone());
            req.metadata_mut()
                .insert("x-ghostbridge-trace-id", trace_meta.clone());
            Ok(req)
        });

    // 4. Arguments mirror MutationEngine::parse_socket_args [name, ports] form.
    //    Ports travel as a CSV string (the parser's string path), sidestepping
    //    the float coercion of google.protobuf.Value numbers.
    let ports_csv = args
        .port
        .iter()
        .map(|p| p.to_string())
        .collect::<Vec<_>>()
        .join(",");

    let request = CallMethodRequest {
        plugin_id: TARGET_PLUGIN.to_string(),
        object_path: object_path.clone(),
        interface_name: String::new(),
        method_name: CREATE_METHOD.to_string(),
        arguments: vec![string_value(&args.name), string_value(&ports_csv)],
        actor_id: String::new(), // resolved from the sled inside MutationEngine
        capability_id: String::new(),
    };

    let response = client
        .call_method(request)
        .await
        .map_err(|status| {
            anyhow::anyhow!(
                "CallMethod failed: {} ({:?})",
                status.message(),
                status.code()
            )
        })?
        .into_inner();

    if !response.success {
        let detail = response
            .error
            .map(|e| format!("{} ({:?})", e.message, e.code()))
            .unwrap_or_else(|| "unknown error".to_string());
        anyhow::bail!("createunixsocket rejected: {detail}");
    }

    println!(
        "{}",
        serde_json::to_string_pretty(&json!({
            "socket": {
                "name": args.name,
                "ports": args.port,
                "protocol": args.protocol,
                "path_hint": args.path,
            },
            "discovered": {
                "bus": bus_label,
                "plugin": TARGET_PLUGIN,
                "object_path": object_path,
            },
            "result": {
                "success": response.success,
                "event_id": response.event_id,
                "event_hash": response.event_hash,
            }
        }))?
    );

    Ok(())
}

/// Build a `google.protobuf.Value` carrying a string.
fn string_value(s: &str) -> prost_types::Value {
    prost_types::Value {
        kind: Some(prost_types::value::Kind::StringValue(s.to_string())),
    }
}

/// Extract immediate child node names from D-Bus introspection XML.
///
/// Children appear as `<node name="child"/>`; the root element carries no
/// `name` attribute, so a simple scan yields exactly the plugin leaves.
fn child_node_names(introspect_xml: &str) -> Vec<String> {
    let mut names = Vec::new();
    let needle = "<node name=\"";
    let mut rest = introspect_xml;
    while let Some(pos) = rest.find(needle) {
        rest = &rest[pos + needle.len()..];
        let Some(end) = rest.find('"') else { break };
        let name = &rest[..end];
        if !name.is_empty() && !name.contains('/') {
            names.push(name.to_string());
        }
        rest = &rest[end + 1..];
    }
    names
}

/// Read the Ghostbridge accountability headers from the live Identity Sled.
///
/// Layout (152-byte repr(C)): `hashed_footprint [u8;32]` at offset 40,
/// `trace_id [u8;16]` at offset 72. Both must match the sled the interceptor
/// reads, so we source them from the same tmpfs file rather than a projection.
fn read_sled_identity() -> anyhow::Result<(String, String)> {
    let bytes = std::fs::read(SLED_PATH)
        .map_err(|e| anyhow::anyhow!("cannot read Identity Sled at {SLED_PATH}: {e}"))?;
    if bytes.len() < 88 {
        anyhow::bail!(
            "Identity Sled at {SLED_PATH} is {} bytes; expected at least 88",
            bytes.len()
        );
    }
    let footprint = &bytes[40..72];
    let trace_id = &bytes[72..88];
    if footprint.iter().all(|&b| b == 0) || trace_id.iter().all(|&b| b == 0) {
        anyhow::bail!(
            "Identity Sled is not provisioned (zero footprint or trace-id); \
             cannot authenticate to the Ghostbridge gate"
        );
    }
    Ok((hex::encode(footprint), hex::encode(trace_id)))
}

