//! MirrorEvent module for unified event enum

use serde_json::Value;

/// Unified event enum representing all data source changes
#[derive(Debug, Clone)]
pub enum MirrorEvent {
    /// OVSDB row change event
    OvsdbRow {
        table_name: String,
        uuid: String,
        delta: Value,
        sequence: u64,
    },
    /// NonNetDb key change event
    NonNet {
        key: String,
        delta: Value,
        sequence: u64,
    },
    /// StateManager plugin event
    Plugin {
        plugin_id: String,
        delta: Value,
        sequence: u64,
    },
    /// ComponentRegistry event
    Registry {
        event: Box<op_grpc_bridge::proto::registry::RegistryEvent>,
        sequence: u64,
    },
    /// Procfs memory info event
    ProcMem { delta: Value, sequence: u64 },
    /// Procfs load average event
    ProcLoad { delta: Value, sequence: u64 },
    /// Procfs static section event
    ProcStatic {
        section: String,
        data: Value,
        sequence: u64,
    },
}

impl MirrorEvent {
    /// Get the target path for this event
    pub fn target_path(&self) -> Option<String> {
        match self {
            MirrorEvent::OvsdbRow {
                table_name, uuid, ..
            } => Some(format!("/org/opdbus/v1/ovsdb/{}/{}", table_name, uuid)),
            MirrorEvent::NonNet { key, .. } => Some(format!("/org/opdbus/v1/nonnet/{}", key)),
            MirrorEvent::Plugin { plugin_id, .. } => {
                Some(format!("/org/opdbus/v1/plugins/{}", plugin_id))
            }
            MirrorEvent::Registry { event, .. } => {
                let component = event.component.as_ref()?;
                let safe = component.component_id.replace(['.', '-', ':'], "_");
                Some(format!("/org/opdbus/v1/registry/{}", safe))
            }
            MirrorEvent::ProcMem { .. } => Some("/org/opdbus/v1/host/meminfo".to_string()),
            MirrorEvent::ProcLoad { .. } => Some("/org/opdbus/v1/host/loadavg".to_string()),
            MirrorEvent::ProcStatic { section, .. } => {
                Some(format!("/org/opdbus/v1/host/{}", section))
            }
        }
    }

    /// Get the sequence number for this event
    pub fn sequence(&self) -> u64 {
        match self {
            MirrorEvent::OvsdbRow { sequence, .. }
            | MirrorEvent::NonNet { sequence, .. }
            | MirrorEvent::Plugin { sequence, .. }
            | MirrorEvent::Registry { sequence, .. }
            | MirrorEvent::ProcMem { sequence, .. }
            | MirrorEvent::ProcLoad { sequence, .. }
            | MirrorEvent::ProcStatic { sequence, .. } => *sequence,
        }
    }
}

//! EventDispatcher module for unified event dispatch

use anyhow::Result;
use op_network::rovs_proxy::OvsdbDbusClient;
use op_state::manager::StateManager;
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::broadcast;
use tracing::{info, warn};

use crate::event::MirrorEvent;
use crate::event_sources::component_registry;
use crate::event_sources::ovsdb;
use crate::event_sources::procfs;
use crate::event_sources::state_manager;
use crate::DbusMirror;

/// Event dispatcher that wires all event sources to the broadcast channel
pub struct EventDispatcher {
    pub broadcast_tx: broadcast::Sender<MirrorEvent>,
    mirror: Arc<DbusMirror>,
    ovsdb_client: Arc<OvsdbDbusClient>,
    state_manager: Option<Arc<StateManager>>,
    grpc_server: Option<Arc<op_grpc_bridge::OperationGrpcServer>>,
    /// Sequence numbers per object path
    sequence_numbers: Arc<std::sync::Mutex<HashMap<String, u64>>>,
}

impl EventDispatcher {
    /// Create a new EventDispatcher
    pub fn new(
        mirror: Arc<DbusMirror>,
        ovsdb_client: Arc<OvsdbDbusClient>,
        state_manager: Option<Arc<StateManager>>,
        grpc_server: Option<Arc<op_grpc_bridge::OperationGrpcServer>>,
    ) -> Self {
        let (broadcast_tx, _) = broadcast::channel(1000);
        Self {
            broadcast_tx,
            mirror,
            ovsdb_client,
            state_manager,
            grpc_server,
            sequence_numbers: Arc::new(std::sync::Mutex::new(HashMap::new())),
        }
    }

    /// Spawn all event sources
    pub async fn spawn_event_sources(&self) -> Result<()> {
        info!("Spawning all event sources");

        // Spawn OVSDB monitor
        ovsdb::spawn_ovsdb_monitor(self.ovsdb_client.clone(), self.broadcast_tx.clone()).await?;

        // Spawn procfs watchers
        procfs::spawn_procfs_inotify_watchers(self.broadcast_tx.clone()).await?;
        procfs::spawn_procfs_loadavg_timer(self.broadcast_tx.clone()).await?;

        // Spawn StateManager watcher
        if let Some(sm) = &self.state_manager {
            state_manager::spawn_state_manager_watcher(sm.clone(), self.broadcast_tx.clone())
                .await?;
        }

        // Spawn ComponentRegistry watcher
        if let Some(grpc) = &self.grpc_server {
            component_registry::spawn_component_registry_watcher(
                grpc.clone(),
                self.broadcast_tx.clone(),
            )
            .await?;
        }

        Ok(())
    }

    /// Run the event loop
    pub async fn run_event_loop(&self) -> Result<()> {
        info!("Starting event loop");

        let mut rx = self.broadcast_tx.subscribe();

        loop {
            match rx.recv().await {
                Ok(event) => {
                    self.publish_delta(&event).await?;
                }
                Err(broadcast::error::RecvError::Lagged(n)) => {
                    warn!("Event dispatcher lagged by {} events", n);
                    // TODO: Implement resync logic
                }
                Err(broadcast::error::RecvError::Closed) => {
                    warn!("Event broadcast channel closed");
                    break;
                }
            }
        }

        Ok(())
    }

    /// Publish delta for an event
    async fn publish_delta(&self, event: &MirrorEvent) -> Result<()> {
        if let Some(path) = event.target_path() {
            // Get current sequence number and increment (scoped to avoid holding guard across .await)
            let _current_seq = {
                let mut seq_map = self.sequence_numbers.lock().unwrap();
                let sequence = seq_map.entry(path.clone()).or_insert(0);
                *sequence += 1;
                *sequence
            };

            // Update current_data with new value and sequence
            let event_seq = event.sequence();
            if let Some(mut entry) = self.mirror.current_data.get_mut(&path) {
                let (data, seq) = &mut *entry;
                *data = event.delta();
                *seq = event_seq;
            } else {
                self.mirror
                    .current_data
                    .insert(path.clone(), (event.delta(), event_seq));
            }

            // Update session pending queues
            let mut sessions_to_drop: Vec<String> = Vec::new();
            for mut session_entry in self.mirror.sessions.iter_mut() {
                session_entry.value_mut().add_event(event.clone());

                if session_entry.value().is_queue_full() {
                    warn!(
                        "Session {} queue full, dropping",
                        session_entry.value().peer_name
                    );
                    sessions_to_drop.push(session_entry.key().clone());
                }
            }
            for key in sessions_to_drop {
                self.mirror.sessions.remove(&key);
            }

            // Emit PropertiesChanged with only changed fields
            self.mirror.publish_object(&path, event.delta()).await?;
        }

        Ok(())
    }
}

/// Extension trait for MirrorEvent to get delta
trait MirrorEventDelta {
    fn delta(&self) -> serde_json::Value;
}

impl MirrorEventDelta for MirrorEvent {
    fn delta(&self) -> serde_json::Value {
        match self {
            MirrorEvent::OvsdbRow { delta, .. }
            | MirrorEvent::NonNet { delta, .. }
            | MirrorEvent::Plugin { delta, .. }
            | MirrorEvent::ProcMem { delta, .. }
            | MirrorEvent::ProcLoad { delta, .. }
            | MirrorEvent::ProcStatic { data: delta, .. } => delta.clone(),
            MirrorEvent::Registry { event, .. } => {
                serde_json::json!({
                    "event_type": event.event_type,
                    "component_id": event.component.as_ref().map(|c| c.component_id.as_str()).unwrap_or(""),
                })
            }
        }
    }
}

//! Canonical Plugin Path and Interface Constants
//!
//! This module defines the SINGLE SOURCE OF TRUTH for all plugin-related
//! paths, interfaces, and naming conventions following FreeDesktop D-Bus
//! standards.
//!
//! ## Canonical Naming Convention
//!
//! ### D-Bus Object Paths
//! ```text
//! /org/opdbus/v1/plugins/{plugin_name}
//! /org/opdbus/v1/plugins/{plugin_name}/{child_object}
//! ```
//!
//! ### D-Bus Interface Names
//! ```text
//! org.opdbus.v1.Plugin.Plugins
//! org.opdbus.v1.Plugin.Plugins.{PluginName}
//! org.opdbus.v1.Plugin.{PluginName}
//! ```
//!
//! ### D-Bus Service Names (Bus Names)
//! ```text
//! org.opdbus.v1
//! org.opdbus.v1.Plugin.{PluginName}
//! ```
//!
//! ### Schema File Paths
//! ```text
//! schemas/plugin/{plugin_name}.json
//! schemas/plugin/freedesktop.json
//! ```
//!
//! ## Forbidden Patterns (DO NOT USE)
//!
//! These patterns are deprecated and MUST NOT be used:
//! - `/opdbus/v1/plugins/` - Missing `org` prefix
//! - `/org/opdbus/plugins/` - Missing `v1` version
//! - `/org/opdbus/v1/` - Missing `plugin` segment
//! - `org.opdbus.plugins.*` - Missing `v1` version
//! - `org.opdbus.v1plugins.*` - Missing dot separator
//!
//! ## Migration Guide
//!
//! Old (deprecated): `/opdbus/v1/plugins/net`
//! New (canonical): `/org/opdbus/v1/plugins/net`
//!
//! Old (deprecated alias): `/org/opdbus/v1/plugin/plugins/net`
//! New (canonical): `/org/opdbus/v1/plugins/net`
//!
//! Old (deprecated): `org.opdbus.NetPlugin`
//! New (canonical): `org.opdbus.v1.Plugin.Plugins.Net`

/// Root D-Bus object path for the op-dbus system
pub const DBUS_ROOT_PATH: &str = "/org/opdbus/v1";

/// Canonical base path for all plugins
pub const PLUGIN_BASE_PATH: &str = "/org/opdbus/v1/plugins";

/// Base interface name for plugin-related interfaces
pub const PLUGIN_BASE_INTERFACE: &str = "org.opdbus.v1.Plugin";

/// Interface for the plugins collection/manager
pub const PLUGINS_INTERFACE: &str = "org.opdbus.v1.Plugin.Plugins";

/// Canonical plugin-host service name (bus name)
pub const BASE_SERVICE_NAME: &str = "org.opdbus.v1.plugins";

/// Schema file directory for plugins
pub const PLUGIN_SCHEMA_DIR: &str = "schemas/plugin";

/// Meta-schema file for plugin validation
pub const PLUGIN_META_SCHEMA: &str = "schemas/plugin/org.opdbus.plugin.schema.json";

/// FreeDesktop plugin schema
pub const FREEDESKTOP_SCHEMA: &str = "schemas/plugin/freedesktop.json";

/// ObjectManager interface (FreeDesktop standard)
pub const OBJECT_MANAGER_INTERFACE: &str = "org.freedesktop.DBus.ObjectManager";

/// Properties interface (FreeDesktop standard)
pub const PROPERTIES_INTERFACE: &str = "org.freedesktop.DBus.Properties";

/// Introspectable interface (FreeDesktop standard)
pub const INTROSPECTABLE_INTERFACE: &str = "org.freedesktop.DBus.Introspectable";

/// Peer interface (FreeDesktop standard)
pub const PEER_INTERFACE: &str = "org.freedesktop.DBus.Peer";

/// Legacy path prefix - DEPRECATED, for migration only
#[deprecated(
    since = "2.0.0",
    note = "Use PLUGIN_BASE_PATH instead. Legacy paths will be removed in v3.0.0"
)]
pub const LEGACY_PLUGIN_PATH: &str = "/opdbus/v1/plugins";

/// Alternative legacy path - DEPRECATED, for migration only
#[deprecated(
    since = "2.0.0",
    note = "Use PLUGIN_BASE_PATH instead. Legacy paths will be removed in v3.0.0"
)]
pub const LEGACY_ALT_PLUGIN_PATH: &str = "/org/opdbus/v1/plugin/plugins";

/// Build the full D-Bus object path for a plugin
///
/// # Example
/// ```
/// use op_plugins::canonical::plugin_path;
///
/// let path = plugin_path("incus");
/// assert_eq!(path, "/org/opdbus/v1/plugins/incus");
/// ```
pub fn plugin_path(name: &str) -> String {
    format!("{}/{}", PLUGIN_BASE_PATH, sanitize_plugin_name(name))
}

/// Build the D-Bus interface name for a specific plugin
///
/// # Example
/// ```
/// use op_plugins::canonical::plugin_interface;
///
/// let iface = plugin_interface("incus");
/// assert_eq!(iface, "org.opdbus.v1.Plugin.Plugins.Incus");
/// ```
pub fn plugin_interface(name: &str) -> String {
    let sanitized = sanitize_plugin_name(name);
    let capitalized = capitalize_plugin_name(&sanitized);
    format!("{}.{}", PLUGINS_INTERFACE, capitalized)
}

/// Build the schema file path for a plugin
///
/// # Example
/// ```
/// use op_plugins::canonical::plugin_schema_path;
///
/// let path = plugin_schema_path("incus");
/// assert_eq!(path, "schemas/plugin/incus.json");
/// ```
pub fn plugin_schema_path(name: &str) -> String {
    format!("{}/{}.json", PLUGIN_SCHEMA_DIR, sanitize_plugin_name(name))
}

/// Build a child object path under a plugin
///
/// # Example
/// ```
/// use op_plugins::canonical::plugin_child_path;
///
/// let path = plugin_child_path("incus", "instance-1");
/// assert_eq!(path, "/org/opdbus/v1/plugins/incus/instance-1");
/// ```
pub fn plugin_child_path(plugin_name: &str, child_id: &str) -> String {
    format!(
        "{}/{}/{}",
        PLUGIN_BASE_PATH,
        sanitize_plugin_name(plugin_name),
        sanitize_child_id(child_id)
    )
}

/// Sanitize a plugin name for use in paths and interface names
///
/// Rules:
/// - Convert to lowercase
/// - Replace hyphens with underscores
/// - Remove any leading/trailing slashes
/// - Must start with a letter (a-z)
pub fn sanitize_plugin_name(name: &str) -> String {
    let sanitized = name
        .trim()
        .trim_matches('/')
        .to_lowercase()
        .replace('-', "_");

    // Ensure it starts with a letter
    if sanitized
        .chars()
        .next()
        .map(|c| c.is_ascii_digit())
        .unwrap_or(false)
    {
        format!("plugin_{}", sanitized)
    } else {
        sanitized
    }
}

/// Capitalize a plugin name for use in interface names
///
/// Converts `plugin_name` to `PluginName`
pub fn capitalize_plugin_name(name: &str) -> String {
    name.split('_')
        .map(|word| {
            let mut chars = word.chars();
            match chars.next() {
                None => String::new(),
                Some(first) => {
                    first.to_uppercase().collect::<String>() + &chars.as_str().to_lowercase()
                }
            }
        })
        .collect()
}

/// Sanitize a child object ID for use in paths
///
/// Rules:
/// - Must not contain path separators
/// - Must be valid UTF-8
/// - Length must be <= 255 characters
fn sanitize_child_id(id: &str) -> String {
    let sanitized: String = id
        .chars()
        .filter(|c| *c != '/' && *c != '\\' && !c.is_control())
        .take(255)
        .collect();

    if sanitized.is_empty() {
        "_".to_string()
    } else {
        sanitized
    }
}

/// Validate a plugin path is in canonical form
///
/// Returns true if the path follows the canonical convention
pub fn is_canonical_plugin_path(path: &str) -> bool {
    path.starts_with(PLUGIN_BASE_PATH)
}

/// Normalize a plugin path to canonical form
///
/// Converts legacy paths to canonical paths
///
/// # Examples
/// - `/opdbus/v1/plugins/net` → `/org/opdbus/v1/plugins/net`
/// - `/org/opdbus/v1/plugin/plugins/net` → `/org/opdbus/v1/plugins/net`
/// - `/org/opdbus/v1/plugins/net` → `/org/opdbus/v1/plugins/net` (already canonical)
pub fn normalize_plugin_path(path: &str) -> Option<String> {
    let trimmed = path.trim().trim_matches('/');

    // Already canonical
    if trimmed.starts_with("org/opdbus/v1/plugins/") {
        return Some(format!("/{}", trimmed));
    }

    // Legacy alias: /org/opdbus/v1/plugin/plugins/{name}
    if let Some(rest) = trimmed.strip_prefix("org/opdbus/v1/plugin/plugins/") {
        let name = rest.split('/').next()?;
        return Some(plugin_path(name));
    }

    // Legacy: /opdbus/v1/plugins/{name}
    if let Some(rest) = trimmed.strip_prefix("opdbus/v1/plugins/") {
        let name = rest.split('/').next()?;
        return Some(plugin_path(name));
    }

    // Just a plugin name
    if !trimmed.contains('/') {
        return Some(plugin_path(trimmed));
    }

    None
}

/// Extract plugin name from a path (canonical or legacy)
///
/// # Examples
/// - `/org/opdbus/v1/plugins/net` → `Some("net")`
/// - `/opdbus/v1/plugins/net` → `Some("net")` (legacy)
/// - `/other/path` → `None`
pub fn extract_plugin_name(path: &str) -> Option<String> {
    let normalized = normalize_plugin_path(path)?;
    normalized
        .strip_prefix(PLUGIN_BASE_PATH)?
        .trim_start_matches('/')
        .split('/')
        .next()
        .map(|s| s.to_string())
}

