pub fn projection_file_path(plugin_id: &str) -> String {
    // Sanitize: replace path separators to keep it a flat filename.
    let safe: String = plugin_id
        .chars()
        .map(|c| if c == '/' || c == '\\' { '_' } else { c })
        .collect();
    format!("{}/{}.json", SHM_PROJECTION_DIR, safe)
}

