    fs::create_dir_all(SHM_PROJECTION_DIR)
        .map_err(|e| anyhow::anyhow!("Cannot create projection dir {}: {}", SHM_PROJECTION_DIR, e))?;

    let path = projection_file_path(plugin_id);
