use anyhow::{Context, Result};
use op_projection::*;
use parking_lot::Mutex;
use std::sync::Arc;
use tracing::{info, warn};
use tracing_subscriber::{EnvFilter, FmtSubscriber};

/// Extract `(plugin_id, path_segments)` from a `RawEntity`.
///
/// Root entities have `entity_id = "<plugin>"` (no colon) → empty path segments.
/// Nested entities have `entity_id = "<plugin>:/<path>/<segments>"`.
fn entity_to_plugin_and_path(entity: &RawEntity) -> (String, Vec<String>) {
    if let Some((plugin_id, path_str)) = entity.entity_id.split_once(':') {
        let path_segments: Vec<String> = path_str
            .trim_start_matches('/')
            .split('/')
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .collect();
        (plugin_id.to_string(), path_segments)
    } else {
        (entity.entity_id.clone(), Vec::new())
    }
}

