// Write the plugin's derived state to the shm projection layer.
//
// The projection IS the state — `/dev/shm/opdbus/projections/<plugin>.json`
// is the single source of truth that the D-Bus tree derives from.
// We write the plugin's full `query_current_state()` (the live derived
// state), NOT the method's return value. A query-only plugin like
// `knowledge` has real state (qdrant stores, embedding config) that no
// method returns — it must be derived from the plugin itself.
//
// If no provider is attached or the query fails, fall back to the
// mutation's `new_value` so the projection still records something.
if change_type != ChangeType::ObjectRemoved {
    let projection_value = if let Some(provider) = &self.plugin_state_provider {
        match provider.query_current_state(&plugin_id).await {
            Some(state) => state,
            None => {
                tracing::debug!(
                    plugin_id = %plugin_id,
                    "query_current_state returned None, falling back to mutation value"
                );
                new_value.clone()
            }
        }
    } else {
        new_value.clone()
    };

    match simd_json::to_string(&projection_value) {
        Ok(json) => {
            if let Err(e) =
                op_core::projection_shm::write_projection(&plugin_id, json.as_bytes())
            {
                tracing::warn!(plugin_id = %plugin_id, error = %e, "Failed to write shm projection");
            }
        }
        Err(e) => {
            tracing::warn!(
                plugin_id = %plugin_id,
                error = %e,
                "Failed to serialize plugin state for shm projection"
            );
        }
    }
}

