    event_chain: Arc<RwLock<EventChain>>,
    ovsdb: Arc<OvsdbDbusClient>,
    nonnet: Arc<NonNetDb>,
) -> Self {
    let (change_tx, _) = broadcast::channel(1024);
    Self {
        event_chain,
        change_tx,
        state_cache: Arc::new(RwLock::new(HashMap::new())),
        dbus_connection: Arc::new(OnceCell::new()),
        dbus_call_limiter: Arc::new(Semaphore::new(32)),
        ovsdb,
        nonnet,
        unix_socket: Arc::new(op_plugins::state_plugins::UnixSocketPlugin::new()),
        plugin_state_provider: None,
    }
}

/// Attach a plugin state provider so mutations derive the plugin's full
/// current state (`query_current_state()`) for the shm projection instead
/// of writing the method's return value.
pub fn with_plugin_state_provider(
    mut self,
    provider: Arc<dyn PluginStateProvider>,
) -> Self {
    self.plugin_state_provider = Some(provider);
    self
}

